create or replace package body t010_finance_pkg as
  function payment(p_principal in number, p_annual_pct in number, p_months in number)
    return number is
  begin
    -- Check for zero months to prevent division by zero in annuity_factor if it were not handled,
    -- and to handle the interest-free case correctly if p_months is 0 (though p_months should be > 0 for a loan).
    if p_months <= 0 then
        return 0;
    end if;

    -- The interest-free case (p_annual_pct = 0) is handled by t010_math.annuity_factor(0, p_months) returning 1/p_months.
    -- The formula for payment is P * [r / (1 - (1+r)^-n)]
    -- If r=0, the factor is 1/n, so payment = P * (1/n).
    -- If r>0, the factor is calculated by annuity_factor.
    return round(p_principal * t010_math.annuity_factor(p_annual_pct / 1200, p_months), 2);
  end payment;
end t010_finance_pkg;
